package core

import "strconv"

// formatNumberLikeJS renders a float64 the way JavaScript's String(number)
// does, because reason strings are compared byte for byte against fixtures
// generated by the TypeScript reference engine.
//
// The two things that matter:
//
//   - A whole number prints with no decimal point: 1000, not 1000.0. Go's
//     %v and %g both agree here, but %.0f would drop 1234.5 to "1234" and
//     %f would pad 1000 to "1000.000000". Neither is the reference.
//   - A fractional number prints the shortest decimal that round-trips:
//     0.12345 * 10000 is 1234.5, and 0.6234499999 * 10000 is
//     6234.499999000001 in BOTH runtimes, because both use IEEE-754 doubles
//     and both print the shortest round-tripping form.
//
// Deliberate, unreachable-from-a-datafile divergence: JSON has no NaN or
// Infinity literal, so a traffic allocation can never be either. If one ever
// arrives from a hand-built Datafile struct, Go prints "NaN" / "+Inf" where
// JavaScript prints "NaN" / "Infinity". Not worth special-casing.
func formatNumberLikeJS(v float64) string {
	return strconv.FormatFloat(v, 'f', -1, 64)
}
